#include <bits/stdc++.h>
using namespace std;

#define DEBUG_MODE 0
typedef long long ll;
typedef pair<int,int> pii;
typedef pair<ll,ll> pll;

#define loop(i, start, end) for(int i=start; i<end; i++)
#define push_back_vector push_back
#define size_of_array(a) ((int)(a).size())
#define fill_array(a,b) memset(a,b,sizeof(a))
#define all_elements_of(a) a.begin(),a.end()
#define first_element first
#define second_element second

const int MAXN=50*100+15;
int source=MAXN-1;
int sink=MAXN-2;

typedef ll flow_type;const flow_type INF_FLOW=1e14;
typedef ll cost_type;const cost_type INF_COST=1e14;

struct Edge {
	int u,v; flow_type cap, flow; cost_type cost;
	flow_type remaining() { return cap - flow; }
};

int total_nodes=MAXN;
vector<int> adjacency[MAXN];
vector<Edge> edges_list;

void add_edge(int u, int v, flow_type cap, cost_type cst) {
	if (DEBUG_MODE) {
		string u_str=to_string(u), v_str=to_string(v);
		if (u==source) u_str="SRC";
		if (u==sink) u_str="SINK";
		if (v==source) v_str="SRC";
		if (v==sink) v_str="SINK";
		cout<<"add edge: "<<u_str<<" "<<v_str<<" "<<cap<<" "<<cst<<endl;
	}
	adjacency[u].push_back(edges_list.size()); edges_list.push_back({u,v,cap,0,cst});
	adjacency[v].push_back(edges_list.size()); edges_list.push_back({v,u,0,0,-cst});
}

ll dist[MAXN], total_cost;
int prev_edge[MAXN];
flow_type capacity_array[MAXN], total_flow;
bool in_queue[MAXN];

void min_cost_max_flow(int s, int t) {
	memset(in_queue, 0, sizeof(in_queue));
	total_flow=0; total_cost=0;
	while (true) {
		fill(dist, dist+total_nodes, INF_COST);
		dist[s]=0;
		memset(prev_edge, -1, sizeof(prev_edge));
		prev_edge[s]=0;
		memset(capacity_array, 0, sizeof(capacity_array));
		capacity_array[s]=INF_FLOW;
		std::queue<int> q; q.push(s); in_queue[s]=true;
		while (!q.empty()) {
			int u=q.front(); q.pop(); in_queue[u]=false;
			for (auto i : adjacency[u]) {
				auto &E=edges_list[i];
				if (E.remaining() && dist[E.v]>dist[u]+E.cost+1e-9) {
					dist[E.v]=dist[u]+E.cost;
					prev_edge[E.v]=i;
					capacity_array[E.v]=min(capacity_array[u], E.remaining());
					if (!in_queue[E.v]) q.push(E.v), in_queue[E.v]=true;
				}
			}
		}
		if (prev_edge[t]<0) break;
		total_flow+=capacity_array[t];
		total_cost+=capacity_array[t]*dist[t];
		for (int v=t; v!=s; v=edges_list[prev_edge[v]].u) {
			edges_list[prev_edge[v]].flow+=capacity_array[t];
			edges_list[prev_edge[v]^1].flow-=capacity_array[t];
		}
	}
}

int main() {
	ios::sync_with_stdio(false);
	ll n,m,k,c,d;
	cin>>n>>m>>k>>c>>d;
	int MAXT=n+k;
	if (DEBUG_MODE) cout<<"MAXT: "<<MAXT<<endl;
	vector<int> a(k);
	for_range(i,0,k) {
		cin>>a[i]; a[i]--;
		add_edge(source, a[i]*MAXT, 1, 0);
	}
	for_range(j,0,MAXT) add_edge(j, sink, k, 0);
	for_range(i,0,m) {
		int x,y; cin>>x>>y; x--; y--;
		for_range(j,0,MAXT-1) for_range(K,1,k+1) {
			add_edge(x*MAXT+j, y*MAXT+j+1, 1, c+d*(2*K-1));
		}
		for_range(j,0,MAXT-1) for_range(K,1,k+1) {
			add_edge(y*MAXT+j, x*MAXT+j+1, 1, c+d*(2*K-1));
		}
	}
	for_range(i,0,n) {
		for_range(j,0,MAXT-1) for_range(K,1,k+1) {
			add_edge(i*MAXT+j, i*MAXT+j+1, 1, c);
		}
	}
	min_cost_max_flow(source, sink);
	if (DEBUG_MODE) cout<<"mincost: "<<total_cost<<" maxflow: "<<total_flow<<endl;
	cout<<total_cost<<endl;
}
